            pop hl		; FileSystem.cls 143
            ld (rd_res), hl		; FileSystem.cls 144
            ld hl, rd_close		; FileSystem.cls 145
            jp rd_go		; FileSystem.cls 146
			ret			; end of #asm

fn_filesystem_eof:		; function eof (asm keyword), FileSystem.cls line 204
            pop hl		; FileSystem.cls 205
            ld e, (hl)		; FileSystem.cls 206
            inc hl		; FileSystem.cls 207
